            base = ord('A') if char.isupper() else ord('a')
            shift = shifts[shift_idx % len(shifts)]
            encrypted = chr((ord(char) - base + shift) % 26 + base)
            result.append(encrypted)
            shift_idx += 1
        else:
            result.append(char)
